const row = () => ({ id: rnd(10), name: pick(NAMES), age: 18 + rnd(43) });
const rows = () => Array.from({ length: rnd(13) }, row);

const STR_POOL = ['', ' ', 'a', 'abc', '0', 'null', '  x ', 'kim'];
function jsonVal(depth: number): unknown {
  const k = rnd(depth > 0 ? 9 : 6);
  switch (k) {
    case 0: return null;
    case 1: return rnd(2) === 0;
    case 2: return -5 + rnd(105);
    case 3: return pick(STR_POOL);
    case 4: return pick([0, 1, -1]) ;
    case 5: return pick(['', 'x']);
    case 6: return Array.from({ length: rnd(4) }, () => jsonVal(depth - 1));
    case 7: case 8: {
      const o: Record<string, unknown> = {};
      const n = rnd(4);
      for (let i = 0; i < n; i++) o[pick(['a', 'b', 'c', '0', 'length'])] = jsonVal(depth - 1);
      return o;
    }
  }
  return null;
}

let fails = 0;
const N = 200000;
for (let i = 0; i < N; i++) {
  const r = rows();
  const a = keyBy(r, (x: any) => x.id), b = cand.byId(r);
  if (JSON.stringify(a) !== JSON.stringify(b) || !isDeepStrictEqual(a, b)) { if (fails++ < 5) console.log('byId mismatch', JSON.stringify(r), a, b); }
