  if (s1 !== s2) { if (fails++ < 5) console.log('totalAge mismatch', r, s1, s2); }
  const v = jsonVal(2);
  const e1 = isEmpty(v), e2 = cand.isBlank(v);
  if (e1 !== e2) { if (fails++ < 5) console.log('isBlank mismatch', JSON.stringify(v), e1, e2); }
}
// fixed examples from the request
const ex = [
  [{"id":3,"name":"kim","age":20},{"id":0,"name":"kim","age":21},{"id":3,"name":"park","age":55},{"id":6,"name":"choi","age":30},{"id":1,"name":"park","age":33},{"id":5,"name":"choi","age":23},{"id":6,"name":"park","age":46}],
  [{"id":1,"name":"choi","age":35},{"id":0,"name":"lee","age":19},{"id":0,"name":"lee","age":57},{"id":3,"name":"choi","age":27}],
  [], 
];
for (const r of ex as any[]) {
  if (JSON.stringify(keyBy(r, (x: any) => x.id)) !== JSON.stringify(cand.byId(r))) { fails++; console.log('ex byId'); }
  if (sumBy(r, 'age') !== cand.totalAge(r)) { fails++; console.log('ex totalAge'); }
}
for (const v of [{}, '', null, true, false, 0, -5, 99, 'abc', [], [[]], {a:{}}]) {
  if (isEmpty(v) !== cand.isBlank(v)) { fails++; console.log('ex isBlank', v); }
}
console.log('done, mismatches =', fails);
EOF
